double meanAbsoluteDeviation(List<double> numbers) {
  if (numbers.isEmpty || !numbers.every((n) => n is double)) return 0.0;

  // 计算平均值
  final average = numbers.reduce((a, b) => a + b).toDouble() / numbers.length;

  // 算术均差计算：每个数与平均值得绝对差之和除以数据点个数。
  var sumOfDifferences = 0.0;
  for (var number in numbers) {
    sumOfDifferences += abs(number - average);
  }

  return sumOfDifferences / numbers.length;
}
```

