int fib(int n) {
  if (n <= 1) return n;

  // Initialize an array to store previously computed values for efficiency.
  final List<int> memo = [0, 1];

  while (memo.length < n + 1) { 
    int nextValue = memo[memo.length - 2]! + memo.last!;

    // Only add new elements when necessary; avoid unnecessary memory usage.      
    if (!isEven(memo.length)) {
      memo.add(nextValue);
    }
  }

  return memo[n];   
}

