/// Returns a list of all prime numbers up to [n].
List<int> countUpTo(int n) {
  if (n < 2) return [];

  List<bool> isPrime = List.filled(n + 1, true);
  isPrime[0] = false;
  isPrime[1] = false;

  for (int i = 2; i <= sqrt(n); ++i) {
    if (!isPrime[i]) continue;

    int p = i * i;
    while (p <= n && !isPrime[p]) {
      isPrime[p] = false;
      p += i;
    }
