    while (low < high) {
      final pi = partition(low, high);
      if ((pi - low) > (high - pi)) {
        quickSortRecursive(pi + 1, high);
        high = pi - 1;
      } else {
        quickSortRecursive(low, pi - 1);
        low = pi + 1;
      }
