List<int> minPath(List<List<int>> grid, int k) {
  int n = grid.length;
  int val = n * n + 1;

  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (grid[i][j] == 1) {
        List<int> temp = [];

        if (i != 0) {
          temp.add(grid[i - 1][j]);
        }

        if (j != 0) {
          temp.add(grid[i][j - 1]);
        }

        if (i != n - 1) {
          temp.add(grid[i + 1][j]);
        }

        if (j != n - 1) {
          temp.add(grid[i][j + 1]);
        }

        if (temp.isNotEmpty) {
          val = temp.reduce((a, b) => a < b ? a : b);
        }
      }
    }
  }

  List<int> ans = [];
  for (int i = 0; i < k; i++) {
    if (i % 2 == 0) {
      ans.add(1);
    } else {
      ans.add(val);
    }
  }

  return ans;
}

